(()=>{const input=document.querySelector('#promo-search'),cards=[...document.querySelectorAll('.coupon')],buttons=[...document.querySelectorAll('[data-category]')].filter(b=>b.tagName==='BUTTON');let category='todos';const norm=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');function update(){let n=0;cards.forEach(c=>{const show=(category==='todos'||category===c.dataset.category)&&norm(c.dataset.search).includes(norm(input.value.trim()));c.hidden=!show;if(show)n++});document.querySelector('#promo-count').textContent=n+' '+(n===1?'promoción':'promociones');document.querySelector('#promo-empty').hidden=n>0}buttons.forEach(b=>b.addEventListener('click',()=>{category=b.dataset.category;buttons.forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});update()}));input.addEventListener('input',update);document.querySelector('#clear-promos').addEventListener('click',()=>{input.value='';category='todos';buttons.forEach(b=>{b.classList.toggle('active',b.dataset.category==='todos');b.setAttribute('aria-pressed',String(b.dataset.category==='todos'))});update()});update()})();